<template><BaseLayout><template #body><FilesNavigation/><main class="agreements"><p v-if="sample" class="sample">SAMPLE AGREEMENTS · Layout testing only. No live signatures or notifications.</p><p v-if="error" role="alert">{{ error }}</p><p v-if="loading">Loading agreements…</p><template v-else-if="!active"><header><h1>Agreements</h1><p>Read and sign your outstanding agreements.</p></header><p v-if="!items.length && !signedDocs.length">No agreements are available.</p><section v-if="signedDocs.some(d=>!['sba_agrement','peak_joining_2026','dld_agrement'].includes(d.field))" class="compliance-folder"><button class="folder-toggle" :aria-expanded="folderOpen" @click="folderOpen=!folderOpen">{{ folderOpen?'▾':'▸' }} Compliance agreements</button><template v-if="folderOpen"><article v-for="doc in signedDocs.filter(d=>!['sba_agrement','peak_joining_2026','dld_agrement'].includes(d.field))" :key="doc.field"><strong>{{ doc.label }}</strong><button class="view-button" @click="preview=doc">View</button></article></template></section><section v-for="folder in ['Subcontractor agreements','Hire agreements']" :key="folder"><button class="folder-toggle" :aria-expanded="extraFolder===folder" @click="extraFolder=extraFolder===folder?'':folder">{{ extraFolder===folder?'▾':'▸' }} {{ folder }}</button><p v-if="extraFolder===folder">No agreements are available in this folder yet.</p></section><section v-for="source in ['WebPage','WebDoc']" :key="source"><h2>{{ source==='WebPage'?'Onboarding agreements':'Issued to you' }}</h2><article v-for="item in items.filter(i=>(i.source==='WebDoc'?'WebDoc':'WebPage')===source)" :key="item.field"><div><strong>{{ item.field==='acap_agreement' ? 'Associate Compliance Agreement' : item.label }}</strong><small>{{ item.signed?'Signed':'Awaiting signature' }}</small></div><button v-if="item.can_sign" type="button" @click="open(item)">Read &amp; sign</button><button class="view-button" v-else-if="signedDocs.some(d=>d.field===item.field)" @click="preview=item">View</button><span v-else class="signed">Signed ✓</span></article></section></template><section v-else><button class="back" type="button" @click="close">‹ Back to agreements</button><h1 v-if="active.field!=='acap_agreement'">{{ active.label }}</h1><AgreementPack v-if="active.field==='acap_agreement'" @signed="close"/><iframe v-else-if="reader.html" :srcdoc="reader.html" sandbox="" title="Agreement document"/><iframe v-else-if="reader.url" :src="reader.url" title="Issued agreement signing"/><template v-if="reader.html && active.field!=='acap_agreement'"><label class="accept"><input type="checkbox" v-model="accepted">{{ sample?'I understand this is a sample for testing.':'I have read and agree to this document.' }}</label><p>Draw your signature below.</p><canvas ref="canvas" width="600" height="200" @pointerdown="start" @pointermove="draw" @pointerup="stop" @pointercancel="stop" aria-label="Draw signature"/><button type="button" class="back" @click="clear">Clear signature</button><button class="submit" type="button" :disabled="!accepted||!hasInk||saving" @click="sign">{{ saving?'Saving…':sample?'Sign sample':'Sign agreement' }}</button></template></section><SignedAgreementPreview v-if="preview" :item="preview" @close="preview=null"/></main></template></BaseLayout></template>
<script setup>
import {ref,onMounted} from 'vue'
import BaseLayout from '@/components/BaseLayout.vue'
import AgreementPack from '@/components/AgreementPack.vue'
import SignedAgreementPreview from '@/components/SignedAgreementPreview.vue'
import {frappeRequest} from 'frappe-ui'
import FilesNavigation from '@/components/FilesNavigation.vue'
import {listAgreements,readAgreement,signAgreement} from '@/data/agreements'
const items=ref([]),sample=ref(false),loading=ref(false),error=ref(''),active=ref(null),reader=ref({}),accepted=ref(false),canvas=ref(null),hasInk=ref(false),saving=ref(false)
const signedLabels={pii_agreement:'Personally Information',spp_agrement:'Stop & Search Policy',mfd_agrement:'Medical Fitness Declaration',vpp_agrement:'Policies & Practices',apn_agrement:'Associate Privacy Notice'}
const extraFolder=ref(''),signedDocs=ref([]),folderOpen=ref(false),preview=ref(null)
let drawing=false
async function load(){loading.value=true;try{const r=await listAgreements();items.value=(Array.isArray(r)?r:r.agreements||[]).filter(i=>['acap_agreement','sba_agrement'].includes(i.field) && !(i.field==='acap_agreement' && i.signed));const docs=await frappeRequest({url:'/api/method/onemotion.api.profile_agreement_pack.signed_documents'});signedDocs.value=(docs?.message??docs).filter(doc=>doc.field!=='nca_agrement').map(doc=>({...doc,label:signedLabels[doc.field]||doc.label}));const peakResponse=await frappeRequest({url:'/api/method/onemotion.api.profile_peak_agreement.status'});const peak=peakResponse?.message??peakResponse;if(peak.visible){items.value.push(peak);if(peak.signed)signedDocs.value.push(peak)}const dldResponse=await frappeRequest({url:'/api/method/onemotion.api.profile_agreement_pack.dld_status'});const dld=dldResponse?.message??dldResponse;if(dld.visible)items.value.push(dld);sample.value=!!r.sample}catch{error.value='Could not load agreements. Please try again.'}finally{loading.value=false}}
async function open(item){error.value='';try{reader.value=item.field==='acap_agreement'?{}:await readAgreement(item);active.value=item;accepted.value=false;hasInk.value=false}catch(e){error.value=e?.messages?.[0]||'Could not open this agreement.'}}
function close(){active.value=null;reader.value={};load()}
function point(e){const r=canvas.value.getBoundingClientRect();return [(e.clientX-r.left)*600/r.width,(e.clientY-r.top)*200/r.height]}
function start(e){drawing=true;canvas.value.setPointerCapture(e.pointerId);const c=canvas.value.getContext('2d');c.beginPath();c.moveTo(...point(e))}
function draw(e){if(!drawing)return;const c=canvas.value.getContext('2d');c.lineWidth=3;c.lineCap='round';c.strokeStyle='#17202b';c.lineTo(...point(e));c.stroke();hasInk.value=true}
function stop(){drawing=false}
function clear(){canvas.value?.getContext('2d').clearRect(0,0,600,200);hasInk.value=false}
async function sign(){saving.value=true;error.value='';try{await signAgreement(active.value,{signature:canvas.value.toDataURL('image/png'),version:reader.value.version,accepted:accepted.value});close()}catch(e){error.value=e?.messages?.[0]||'Could not save your signature. Please try again.'}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>.agreements{padding:.5rem .35rem 6rem;color:#17202b}h1{font-size:1.4rem;font-weight:650}h2{font-size:.8rem;color:#687586;margin:1.4rem 0 .6rem}p{font-size:.85rem;line-height:1.5}article{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem;border:1px solid #e3e8ee;border-radius:12px;margin:.65rem 0;background:white}strong{font-size:.9rem}small{display:block;font-size:.75rem;color:#687586;margin-top:.3rem}button{border:0;border-radius:8px;background:#a61d1d;color:white;padding:.6rem .8rem;font-size:.8rem;min-height:40px;cursor:pointer}.back{background:none;color:#a61d1d;padding-left:0}.signed{color:#166534;font-size:.8rem}.sample{background:#fff2cb;color:#795500;border-radius:8px;padding:.75rem;font-size:.75rem}iframe{width:100%;height:55dvh;border:1px solid #e3e8ee;border-radius:10px;margin:1rem 0;background:white}canvas{width:100%;height:130px;touch-action:none;border:1px solid #aab5c3;border-radius:10px;background:white}.accept{display:flex;align-items:flex-start;gap:.65rem;font-size:.85rem}.accept input{margin-top:.2rem}.submit{display:block;width:100%;margin-top:1rem}button:disabled{opacity:.45;cursor:default}.agreements:has(.signing-page){padding-bottom:0}.folder-toggle{width:100%;text-align:left;margin-top:.65rem;background:#edf1f5;color:#17202b;border:1px solid #dfe5ec;font-weight:600;min-height:52px}.view-button{background:#edf1f5;color:#a61d1d;border:1px solid #dfe5ec}.compliance-folder article{padding:.5rem .75rem;margin:.4rem 0;gap:.75rem}.compliance-folder .view-button{flex-shrink:0;min-height:40px;padding:.4rem .8rem}article strong{font-weight:400}</style>
